const NOTES=[
 ['OOP','Class & Object','Class = blueprint. Object = instance of a class.'],['OOP','Encapsulation','Use private data and public methods to control access.'],['OOP','Abstraction','Expose essential operations and hide implementation details.'],['OOP','Inheritance','Derived classes reuse and extend base-class behavior.'],['OOP','Polymorphism','Compile-time: overloading. Runtime: virtual functions/overriding.'],['OOP','Constructor','Runs when an object is created and initializes members.'],['OOP','Destructor','Runs when an object lifetime ends and performs cleanup.'],['OOP','Composition','HAS-A relationship: one class contains another object.'],['DSA','Array','Indexed, contiguous-style storage; direct access is O(1).'],['DSA','Linked List','Nodes connected by NEXT references; sequential access is O(n).'],['DSA','Doubly Linked List','Nodes contain PREV and NEXT references, enabling traversal in both directions.'],['DSA','Stack','LIFO; Push, Pop and Peek are typically O(1).'],['DSA','Queue','FIFO; Enqueue/Dequeue can be O(1) with a suitable implementation.'],['DSA','Binary Tree','Each node has at most two children.'],['DSA','BST','Left subtree values are smaller and right subtree values are larger.'],['DSA','Graph','Vertices + edges; BFS/DFS are O(V+E).'],['DSA','Hashing','Maps keys to buckets; average lookup is O(1).'],['Algorithms','Linear Search','Checks elements one by one; O(n).'],['Algorithms','Binary Search','Requires sorted data; O(log n).'],['Algorithms','Bubble Sort','Repeatedly compares adjacent elements; O(n²) worst.'],['Algorithms','Selection Sort','Selects the smallest remaining element; O(n²).'],['Algorithms','Insertion Sort','Inserts each item into the sorted left portion; O(n²) worst.'],['Algorithms','Merge Sort','Divide and conquer sorting; O(n log n), O(n) auxiliary space.'],['Analysis','Big-O','Describes asymptotic growth of time or space as n increases.']
];
function conceptControls(kind){const topics=kind==='oop'?OOP_TOPICS:DSA_TOPICS;const opts=Object.entries(topics).map(([k,v])=>`<option value="${k}">${v.title}</option>`).join('');return `<div class="form"><div class="field"><label>CONCEPT</label><select id="concept-select">${opts}</select></div><button class="btn primary full" type="button" onclick="showConcept('${kind}')">Visualize Concept</button><div id="concept-summary" class="concept-summary"></div><div class="help">Choose a concept and watch the visual model update instantly. No backend request is needed for concept lessons.</div></div>`}
function conceptVisual(kind,key){const t=(kind==='oop'?OOP_TOPICS:DSA_TOPICS)[key];const common=(title,body)=>`<div class="concept-visual"><div class="concept-title">${esc(title)}</div>${body}</div>`;
 if(t.visual==='class-object')return common(t.title,`<div class="oop-diagram"><div class="diagram-box"><b>CLASS</b><strong>Student</strong><span>name</span><span>rollNo</span><span>display()</span></div><div class="diagram-arrow">creates →</div><div class="diagram-box object"><b>OBJECT</b><strong>s1</strong><span>name = Abhinav</span><span>rollNo = 101</span></div></div>`);
 if(t.visual==='encapsulation')return common(t.title,`<div class="layer-diagram"><div class="private-layer"><b>PRIVATE DATA</b><span>balance</span><span>password</span></div><div class="gate">PUBLIC METHODS<br><b>deposit()</b> &nbsp; <b>withdraw()</b></div><div class="outside">Outside code → uses controlled interface</div></div>`);
 if(t.visual==='abstraction')return common(t.title,`<div class="abstraction-diagram"><div class="user-box">USER<br><b>push(10)</b></div><div class="flow">→</div><div class="interface-box">PUBLIC INTERFACE<br><b>Stack::push()</b></div><div class="flow">→</div><div class="hidden-box">HIDDEN IMPLEMENTATION<br>array / linked nodes / pointer updates</div></div>`);
 if(t.visual==='inheritance')return common(t.title,`<div class="inherit-diagram"><div class="diagram-box"><b>BASE CLASS</b><strong>Animal</strong><span>eat()</span><span>sleep()</span></div><div class="down-arrow">↓ inherited by</div><div class="inherit-row"><div class="diagram-box object"><b>DERIVED</b><strong>Dog</strong><span>bark()</span></div><div class="diagram-box object"><b>DERIVED</b><strong>Cat</strong><span>meow()</span></div></div></div>`);
 if(t.visual==='polymorphism')return common(t.title,`<div class="poly-diagram"><div class="diagram-box"><b>COMMON INTERFACE</b><strong>draw()</strong></div><div class="poly-row"><div class="diagram-box object"><b>Circle</b><span>draw() → ○</span></div><div class="diagram-box object"><b>Rectangle</b><span>draw() → ▭</span></div><div class="diagram-box object"><b>Triangle</b><span>draw() → △</span></div></div></div>`);
 if(t.visual==='lifecycle')return common(t.title,`<div class="lifecycle"><span>Object declared</span><b>→</b><span class="active">Constructor</span><b>→</b><span>Object used</span><b>→</b><span class="active">Destructor</span><b>→</b><span>Cleanup</span></div>`);
 if(t.visual==='composition')return common(t.title,`<div class="composition"><div class="diagram-box"><b>WHOLE</b><strong>ExperimentManager</strong><span>arrayModule</span></div><div class="composition-link">HAS-A →</div><div class="diagram-box object"><b>PART</b><strong>ArrayModule</strong><span>data + methods</span></div></div>`);
 if(t.visual==='complexity')return common(t.title,`<div class="complexity-bars"><div><span>O(1)</span><i style="width:10%"></i></div><div><span>O(log n)</span><i style="width:25%"></i></div><div><span>O(n)</span><i style="width:48%"></i></div><div><span>O(n log n)</span><i style="width:70%"></i></div><div><span>O(n²)</span><i style="width:94%"></i></div></div>`);
 if(t.visual==='doubly-list')return common(t.title,`<div class="dlist-concept"><div class="dconcept-node"><span>NULL</span><b>10</b><span>→</span></div><div class="dconcept-link">⇄</div><div class="dconcept-node"><span>←</span><b>20</b><span>→</span></div><div class="dconcept-link">⇄</div><div class="dconcept-node"><span>←</span><b>30</b><span>NULL</span></div><small>PREV ← DATA → NEXT</small></div>`);if(t.visual==='array-list')return common(t.title,`<div class="compare-visual"><div><b>ARRAY</b><div class="mini-array">10&nbsp;&nbsp;20&nbsp;&nbsp;30&nbsp;&nbsp;40</div><small>Direct index access</small></div><div class="compare-vs">VS</div><div><b>LINKED LIST</b><div class="mini-list">10 → 20 → 30 → 40 → NULL</div><small>Follow NEXT references</small></div></div>`);
 if(t.visual==='stack')return common(t.title,`<div class="concept-stack"><div class="cstack">30 <small>TOP</small></div><div class="cstack">20</div><div class="cstack">10 <small>BOTTOM</small></div><p>POP → 30</p></div>`);
 if(t.visual==='queue')return common(t.title,`<div class="concept-queue"><span>FRONT</span><div>10</div><div>20</div><div>30</div><span>REAR</span><p>DEQUEUE → 10</p></div>`);
 if(t.visual==='tree')return common(t.title,`<div class="concept-tree"><div class="ctree-node">50</div><div class="ctree-children"><div><span>30</span><small>LEFT: smaller</small></div><div><span>70</span><small>RIGHT: larger</small></div></div></div>`);
 if(t.visual==='graph')return common(t.title,`<div class="concept-graph"><svg viewBox="0 0 500 180"><line x1="100" y1="90" x2="250" y2="45"/><line x1="100" y1="90" x2="250" y2="135"/><line x1="250" y1="45" x2="400" y2="90"/><line x1="250" y1="135" x2="400" y2="90"/><circle cx="100" cy="90" r="24"/><circle cx="250" cy="45" r="24"/><circle cx="250" cy="135" r="24"/><circle cx="400" cy="90" r="24"/><text x="100" y="96">A</text><text x="250" y="51">B</text><text x="250" y="141">C</text><text x="400" y="96">D</text></svg><small>V = vertices, E = edges</small></div>`);
 if(t.visual==='hash')return common(t.title,`<div class="hash-concept"><div class="hash-key">KEY 42</div><div>→ hash(key) →</div><div class="hash-bucket">Bucket 2<br><b>42</b></div><small>Example: 42 % 10 = 2</small></div>`);
 if(t.visual==='search')return common(t.title,`<div class="search-visual"><div class="search-row">10 <b>20</b> <strong>30</strong> 40 50</div><div class="search-pointer">↑ target</div><small>Linear checks sequentially; binary checks the middle of a sorted range.</small></div>`);
 return common(t.title,`<div class="sort-visual"><div>50</div><b>→</b><div>20</div><b>→</b><div>40</div><b>→</b><div>10</div><p>Compare → move/swap → repeat → <strong>10, 20, 40, 50</strong></p></div>`);
}
function showConcept(kind){const key=$('concept-select').value;state.concept.topic=key;const t=(kind==='oop'?OOP_TOPICS:DSA_TOPICS)[key];$('concept-summary').innerHTML=`<b>${esc(t.title)}</b><span>${esc(t.summary)}</span>`;count(0);$('status').textContent='Concept ready';$('operation').textContent=t.title;setComplexity({time:t.time,space:t.space,note:'Concept lesson — complexity is shown only when it is meaningful.'});logSteps(t.steps);$('visualArea').innerHTML=conceptVisual(kind,key);$('animationPanel').classList.add('hidden');operationCount++;$('opCount').textContent=operationCount;history.push({module:kind==='oop'?'OOP':'DSA CONCEPTS',operation:t.title,input:'Concept lesson',result:t.summary,time:t.time});renderHistory();}
function renderNotes(){const q=(($('notes-search')||{}).value||'').trim().toLowerCase();const filter=(($('notes-filter')||{}).value||'ALL');const rows=NOTES.filter(n=>(filter==='ALL'||n[0]===filter)&&(!q||n.join(' ').toLowerCase().includes(q)));$('visualArea').innerHTML=`<div class="notes-board"><div class="notes-tools"><input id="notes-search" value="${esc(q)}" placeholder="Search notes…" autocomplete="off"><select id="notes-filter"><option ${filter==='ALL'?'selected':''}>ALL</option><option ${filter==='OOP'?'selected':''}>OOP</option><option ${filter==='DSA'?'selected':''}>DSA</option><option ${filter==='Algorithms'?'selected':''}>Algorithms</option><option ${filter==='Analysis'?'selected':''}>Analysis</option></select></div><div class="notes-grid">${rows.map((n,i)=>`<article class="note-card"><small>${esc(n[0])}</small><h4>${esc(n[1])}</h4><p>${esc(n[2])}</p></article>`).join('')||'<div class="empty">No matching notes.</div>'}</div></div>`;count(rows.length);$('status').textContent=`${rows.length} notes`;$('operation').textContent='Study & Revision';setComplexity({time:'—',space:'—',note:'Use the search and category filter to revise concepts quickly. Detailed visual lessons are available under OOP Concepts and DSA Concepts.'});logSteps(['Select OOP Concepts or DSA Concepts for an interactive visualization.','Use Notes to revise definitions, relationships and common complexities.','Return to any data-structure module to practice the actual operation.']);$('animationPanel').classList.add('hidden');$('notes-search').addEventListener('input',renderNotes);$('notes-filter').addEventListener('change',renderNotes);}

function controls(){let h='';if(moduleName==='oop')h=conceptControls('oop');else if(moduleName==='dsa-concepts')h=conceptControls('dsa');else if(moduleName==='notes'){h='<div class="form"><div class="help"><b>Notes & Revision:</b> Search definitions, relationships and complexity reminders. The full notes collection appears in the visualization area.</div><button class="btn primary full" type="button" onclick="renderNotes()">Open Notes</button></div>';}else if(moduleName==='array')h=`<div class="form"><div class="two"><div class="field"><label>NUMBER OF ELEMENTS</label><input id="array-n" type="number" min="1" max="30" placeholder="5"></div><button class="btn" onclick="makeArrayFields()">Generate Input Fields</button></div><div id="arrayFields" class="generated-grid"></div><button class="btn primary full" onclick="run('create')">Create Array</button><div class="two"><div class="field"><label>INDEX</label><input id="array-index" type="number" placeholder="2"></div><div class="field"><label>VALUE</label><input id="array-value" type="number" placeholder="99"></div></div><div class="btns"><button class="btn primary" onclick="run('insert')">＋ Insert</button><button class="btn danger" onclick="run('delete')">− Delete</button><button class="btn" onclick="run('search')">⌕ Search</button><button class="btn" onclick="run('traverse')">→ Traverse</button></div><div class="help">Creation follows the same logic as a C++ loop: <b>for (int i = 0; i &lt; n; i++) cin &gt;&gt; arr[i];</b></div></div>`;
else if(moduleName==='doubly-linked-list')h=`<div class="form"><div class="field"><label>VALUES</label><input id="dlinked-values" name="dlinked_values_fresh" autocomplete="off" spellcheck="false" placeholder="10,20,30,40"></div><button class="btn primary full" onclick="run('create')">Create Doubly Linked List</button><div class="two"><div class="field"><label>POSITION</label><input id="dlinked-index" name="dlinked_index_fresh" type="number" autocomplete="off" placeholder="1"></div><div class="field"><label>VALUE</label><input id="dlinked-value" name="dlinked_value_fresh" type="number" autocomplete="off" placeholder="99"></div></div><div class="btns"><button class="btn primary" onclick="run('insert')">＋ Insert</button><button class="btn danger" onclick="run('delete')">− Delete</button><button class="btn" onclick="run('traverse')">⇄ Traverse</button><button class="btn" onclick="run('reverse')">↶ Reverse</button></div><div class="help"><b>Two-way pointers:</b> PREV moves backward and NEXT moves forward. Try clicking a node after creation.</div></div>`;
else if(moduleName==='linked-list')h=`<div class="form"><div class="field"><label>VALUES</label><input id="linked-values" name="linked_list_values_fresh" autocomplete="new-password" spellcheck="false" placeholder="10,20,30,40,50"></div><button class="btn primary full" onclick="run('create')">Create List</button><div class="two"><div class="field"><label>POSITION</label><input id="linked-index" name="linked_list_index_fresh" type="number" autocomplete="off" placeholder="1"></div><div class="field"><label>VALUE</label><input id="linked-value" name="linked_list_value_fresh" type="number" autocomplete="off" placeholder="99"></div></div><div class="btns"><button class="btn primary" onclick="run('insert')">＋ Insert</button><button class="btn danger" onclick="run('delete')">− Delete</button><button class="btn" onclick="run('traverse')">→ Traverse</button><button class="btn" onclick="run('reverse')">↶ Reverse</button></div></div>`;
else if(moduleName==='stack')h=`<div class="form stack-controls"><div class="field"><label>VALUE FOR PUSH</label><input id="stack-value" name="stack_value_fresh" type="number" inputmode="numeric" autocomplete="off" placeholder="Enter value, e.g. 10" onkeydown="if(event.key==='Enter')run('push')"></div><div class="btns"><button class="btn primary" type="button" onclick="run('push')">↑ Push</button><button class="btn danger" type="button" onclick="run('pop')">↓ Pop</button><button class="btn" type="button" onclick="run('peek')">⌃ Peek</button><button class="btn" type="button" onclick="run('display')">▤ Display</button></div><div id="stackResult" class="stack-result">Choose an operation. Push needs a value; Pop, Peek and Display use the current stack.</div><div class="help"><b>One operation at a time:</b> Push adds a value at TOP, Pop removes TOP, Peek reads TOP without changing the stack, and Display shows the current stack.</div></div>`;
else if(moduleName==='queue')h=`<div class="form"><div class="field"><label>VALUE</label><input id="queue-value" name="queue_value_fresh" type="number" autocomplete="off" placeholder="10"></div><div class="btns"><button class="btn primary" onclick="run('enqueue')">→ Enqueue</button><button class="btn danger" onclick="run('dequeue')">← Dequeue</button><button class="btn" onclick="run('front')">Front</button><button class="btn" onclick="run('display')">Display</button></div></div>`;
else if(moduleName==='tree')h=`<div class="form"><div class="field"><label>VALUE</label><input id="tree-value" name="tree_value_fresh" type="number" autocomplete="off" placeholder="50"></div><div class="btns"><button class="btn primary" onclick="run('insert')">＋ Insert Node</button><button class="btn" onclick="run('search')">⌕ Search</button><button class="btn" onclick="run('inorder')">Inorder</button><button class="btn" onclick="run('preorder')">Preorder</button><button class="btn" onclick="run('postorder')">Postorder</button></div></div>`;
else if(moduleName==='graph')h=`<div class="form"><div class="two"><div class="field"><label>VERTEX</label><input id="graph-vertex" name="graph_vertex_fresh" autocomplete="off" placeholder="A"></div><button class="btn primary" onclick="run('addVertex')">＋ Add Vertex</button></div><div class="two"><div class="field"><label>FROM</label><input id="graph-from" name="graph_from_fresh" autocomplete="off" placeholder="A"></div><div class="field"><label>TO</label><input id="graph-to" name="graph_to_fresh" autocomplete="off" placeholder="B"></div></div><button class="btn primary full" onclick="run('addEdge')">Connect Edge</button><div class="two"><div class="field"><label>START VERTEX</label><input id="graph-start" name="graph_start_fresh" autocomplete="off" placeholder="A"></div><button class="btn" onclick="run('bfs')">BFS</button></div><button class="btn" onclick="run('dfs')">DFS</button></div>`;
else if(moduleName==='hashing')h=`<div class="form"><div class="field"><label>KEY</label><input id="hash-value" name="hash_value_fresh" type="number" autocomplete="off" placeholder="42"></div><div class="btns"><button class="btn primary" onclick="run('insert')">＋ Insert</button><button class="btn danger" onclick="run('delete')">− Delete</button><button class="btn" onclick="run('search')">⌕ Search</button><button class="btn" onclick="run('display')">Display</button></div><div class="help">Hash function: <b>index = |key| % 10</b>. Collisions stay together in a bucket chain.</div></div>`;
else if(moduleName==='searching')h=`<div class="form"><div class="field"><label>ARRAY</label><input id="search-values" name="search_values_fresh" autocomplete="new-password" spellcheck="false" placeholder="10,20,30,40,50"></div><div class="field"><label>SEARCH VALUE</label><input id="search-value" name="search_value_fresh" type="number" autocomplete="off" placeholder="30"></div><div class="btns"><button class="btn primary" onclick="run('linear')">Linear Search</button><button class="btn" onclick="run('binary')">Binary Search</button></div></div>`;
else h=`<div class="form"><div class="field"><label>ARRAY</label><input id="sort-values" name="sort_values_fresh" autocomplete="new-password" placeholder="50,20,40,10,30"></div><div class="btns"><button class="btn primary" onclick="run('bubble')">Bubble Sort</button><button class="btn" onclick="run('selection')">Selection Sort</button><button class="btn" onclick="run('insertion')">Insertion Sort</button></div></div>`;$('controlsArea').innerHTML=h; clearCurrentModuleInputs()}
function clearCurrentModuleInputs(){
  document.querySelectorAll('#controlsArea input').forEach((el)=>{ el.value=''; el.defaultValue=''; el.setAttribute('autocomplete','off'); });
}
function parseVals(s){const raw=String(s??'').trim();if(!raw)throw Error('Enter comma-separated numeric values.');const parts=raw.split(',').map(x=>x.trim());if(parts.some(x=>x===''))throw Error('Do not leave an empty value between commas.');if(parts.some(x=>!/^[-+]?\d+(?:\.\d+)?$/.test(x)))throw Error('Use only numbers separated by commas, for example: 10,20,30,40.');const a=parts.map(Number);if(a.some(x=>!Number.isFinite(x)))throw Error('Enter valid numeric values.');return a}
function detailed(op,d,raw,before,after){const o=op.toLowerCase(),a=before.array||[],f=after.array||[];if(o.includes('create array'))return d.steps;if(o==='insertion'||o==='deletion'||o==='traversal'||o.includes('search')||o.includes('sort'))return d.steps;if(o.includes('linked list'))return d.steps;if(o.startsWith('stack')||o.startsWith('queue')||o.includes('tree')||o==='bfs'||o==='dfs'||o.includes('hash'))return d.steps;return d.steps||[]}
function arrayFrames(d,before,after,raw){const op=d.operation.toLowerCase(),a=before.array||[],f=after.array||[],fs=[];if(op.includes('create array')){fs.push(frame('Begin with an empty array. The program first asks the user for the number of elements.',{array:[]},{pointerLabel:'START CREATION'}));for(let i=0;i<f.length;i++){fs.push(frame(`Loop iteration ${i+1}: i = ${i}. Read the value ${f[i]} from the user and store it at array index ${i}.`,{array:f.slice(0,i).concat(['']).concat(Array(Math.max(0,f.length-i-1)).fill(''))},{pointer:i,pointerLabel:`arr[${i}] = ${f[i]}`}));}fs.push(frame(`The loop finishes after i reaches ${f.length}. Final array: [${f.join(', ')}].`,{array:f},{pointerLabel:'ARRAY CREATED'}));}
else if(op==='insertion'){const p=Number(raw.index),v=Number(raw.value);fs.push(frame(`Target index ${p} is selected. The existing array is [${a.join(', ')}].`,{array:a},{pointer:p,pointerLabel:`TARGET INDEX ${p}`}));let s=a.slice();s.push('');for(let i=a.length-1;i>=p;i--){s[i+1]=s[i];s[i]='';fs.push(frame(`Move ${a[i]} from index ${i} to index ${i+1}. This shift creates room at index ${i}.`,{array:s},{highlight:[i,i+1],pointer:i,pointerLabel:`SHIFT ${a[i]} → ${i+1}`}));}s[p]=v;fs.push(frame(`Write the new value ${v} into the open slot at index ${p}.`,{array:s},{highlight:[p],pointer:p,pointerLabel:'INSERT'}));fs.push(frame(`Insertion is complete.`,{array:f},{highlight:[p],pointerLabel:'FINAL ARRAY'}));}
else if(op==='deletion'){const p=Number(raw.index);fs.push(frame(`Select ${a[p]} at index ${p} for deletion.`,{array:a},{highlight:[p],pointer:p,pointerLabel:'DELETE'}));let s=a.slice();for(let i=p;i<a.length-1;i++){s[i]=s[i+1];fs.push(frame(`Copy ${a[i+1]} from index ${i+1} to index ${i} to close the gap.`,{array:s},{highlight:[i,i+1],pointer:i,pointerLabel:'SHIFT LEFT'}));}s.pop();fs.push(frame(`Remove the extra final slot.`,{array:s},{pointerLabel:'RESIZE'}));fs.push(frame(`Deletion is complete.`,{array:f},{pointerLabel:'FINAL ARRAY'}));}
else if(op.includes('linear search')){for(let i=0;i<a.length;i++){fs.push(frame(`Compare target ${raw.value} with value ${a[i]} at index ${i}.`,{array:a},{highlight:[i],pointer:i,pointerLabel:`CHECK index ${i}`}));if(a[i]===Number(raw.value)){fs.push(frame(`Match found: ${raw.value} is stored at index ${i}. Stop.`,{array:a},{highlight:[i],pointer:i,pointerLabel:'FOUND'}));break}}if(!a.includes(Number(raw.value)))fs.push(frame(`All indices were checked. ${raw.value} is not present.`,{array:a},{pointerLabel:'NOT FOUND'}));}
else if(op.includes('binary search')){const x=a.slice().sort((x,y)=>x-y);let l=0,h=x.length-1;fs.push(frame(`Binary search uses sorted data: [${x.join(', ')}]. LEFT = 0 and RIGHT = ${h}.`,{array:x},{pointerLabel:'SEARCH RANGE'}));while(l<=h){const m=Math.floor((l+h)/2);fs.push(frame(`Calculate MID = floor((${l}+${h})/2) = ${m}. Compare ${x[m]} with target ${raw.value}.`,{array:x},{highlight:[m],pointer:m,pointerLabel:`MID = ${m}`}));if(x[m]===Number(raw.value)){fs.push(frame(`The middle value matches ${raw.value}. Search succeeds.`,{array:x},{highlight:[m],pointer:m,pointerLabel:'FOUND'}));break}if(x[m]<Number(raw.value))l=m+1;else h=m-1}if(!x.includes(Number(raw.value)))fs.push(frame(`No search range remains. Target is not found.`,{array:x},{pointerLabel:'NOT FOUND'}));}
else if(op.includes('sort')){let s=a.slice();if(op.includes('bubble')){for(let p=0;p<s.length-1;p++)for(let j=0;j<s.length-p-1;j++){fs.push(frame(`Pass ${p+1}: compare adjacent values ${s[j]} and ${s[j+1]}.`,{array:s},{highlight:[j,j+1],pointer:j,pointerLabel:'COMPARE'}));if(s[j]>s[j+1]){[s[j],s[j+1]]=[s[j+1],s[j]];fs.push(frame(`They are out of order, so swap them.`,{array:s},{highlight:[j,j+1],pointer:j,pointerLabel:'SWAP'}));}}}else if(op.includes('selection')){for(let i=0;i<s.length-1;i++){let m=i;fs.push(frame(`Start position ${i}. Assume ${s[i]} is the smallest remaining value.`,{array:s},{highlight:[i],pointer:i,pointerLabel:'CURRENT MINIMUM'}));for(let j=i+1;j<s.length;j++){fs.push(frame(`Compare candidate ${s[j]} at index ${j} with current minimum ${s[m]}.`,{array:s},{highlight:[m,j],pointer:j,pointerLabel:'COMPARE'}));if(s[j]<s[m])m=j}if(m!==i){[s[i],s[m]]=[s[m],s[i]];fs.push(frame(`Place the smallest value ${s[i]} into sorted position ${i}.`,{array:s},{highlight:[i],pointer:i,pointerLabel:'PLACE MINIMUM'}));}}}else{for(let i=1;i<s.length;i++){const key=s[i];let j=i-1;fs.push(frame(`Take ${key} as the KEY. The left portion is already sorted.`,{array:s},{highlight:[i],pointer:i,pointerLabel:`KEY = ${key}`}));while(j>=0&&s[j]>key){s[j+1]=s[j];fs.push(frame(`Shift ${s[j]} one position right because it is greater than KEY ${key}.`,{array:s},{highlight:[j,j+1],pointer:j,pointerLabel:'SHIFT'}));j--}s[j+1]=key;fs.push(frame(`Insert KEY ${key} at index ${j+1}.`,{array:s},{highlight:[j+1],pointer:j+1,pointerLabel:'INSERT KEY'}));}}fs.push(frame(`Sorting is complete. FINAL ARRAY = [${f.join(', ')}].`,{array:f},{pointerLabel:'FINAL SORTED ARRAY'}));}return fs}
function genericFrames(module,d,before,after,raw){if(['array','searching','sorting'].includes(moduleName))return arrayFrames(d,before,after,raw);const fs=[],a=after.array||before.array||[];if(moduleName==='linked-list'){if(d.operation==='Create Linked List'){fs.push(frame('HEAD points to node 0. The node stores DATA = '+a[0]+' and its NEXT points to node 1.',{array:a},{pointerIndex:0,pointerLabel:'HEAD → node 0'}));a.forEach((v,i)=>fs.push(frame(i<a.length-1?`Node ${i}: DATA = ${v}. NEXT points to node ${i+1}, where DATA = ${a[i+1]} is stored.`:`Node ${i}: DATA = ${v}. NEXT = NULL because this is the last node.`,{array:a},{highlight:[i],pointerIndex:i,pointerLabel:`NODE ${i}`})));fs.push(frame(`Following HEAD → NEXT repeatedly gives ${a.join(' → ')} → NULL.`,{array:a},{pointerLabel:'LIST COMPLETE'}));}else a.forEach((v,i)=>fs.push(frame(`Current pointer is at node ${i}. DATA = ${v}. Follow NEXT to the next node.`,{array:a},{highlight:[i],pointerIndex:i,pointerLabel:`NODE ${i}`})));if(!fs.length)fs.push(frame(d.message,{array:a}));return fs}if(moduleName==='doubly-linked-list'){if(d.operation==='Create Doubly Linked List'){fs.push(frame('HEAD points to node 0. PREV = NULL and NEXT points forward to node 1.',{array:a},{pointerIndex:0,pointerLabel:'HEAD → node 0'}));a.forEach((v,i)=>fs.push(frame(i===0?`Node 0: DATA = ${v}. PREV = NULL. NEXT points to node 1.`:i===a.length-1?`Node ${i}: DATA = ${v}. PREV points to node ${i-1}. NEXT = NULL.`:`Node ${i}: DATA = ${v}. PREV → node ${i-1}, NEXT → node ${i+1}.`,{array:a},{highlight:[i],pointerIndex:i,pointerLabel:`NODE ${i}`})));fs.push(frame(`The list can be traversed forward ${a.join(' → ')} and backward ${a.slice().reverse().join(' → ')}.`,{array:a},{pointerLabel:'TWO-WAY TRAVERSAL'}));}else a.forEach((v,i)=>fs.push(frame(`Node ${i}: DATA = ${v}. PREV ${i?'→ node '+(i-1):'= NULL'}; NEXT ${i<a.length-1?'→ node '+(i+1):'= NULL'}.`,{array:a},{highlight:[i],pointerIndex:i,pointerLabel:`NODE ${i}`})));if(!fs.length)fs.push(frame(d.message,{array:a}));return fs}if(moduleName==='stack'){const b=before.array||before.stack||[];const f=after.array||after.stack||[];const action=(d.operation||'').toLowerCase();if(action.includes('push')){const v=f[f.length-1];fs.push(frame(`Before PUSH, the stack is [${b.join(', ')}]. TOP is ${b.length?b[b.length-1]:'empty'}.`,{array:b},{pointerLabel:'BEFORE PUSH'}));fs.push(frame(`Create a new element containing ${v} and place it above the current TOP.`,{array:b.concat([v])},{highlight:[f.length-1],pointerLabel:'NEW ELEMENT'}));fs.push(frame(`Update TOP to point to ${v}. The resultant stack is [${f.join(', ')}].`,{array:f},{highlight:[f.length-1],pointerLabel:'TOP → '+v}));}else if(action.includes('pop')){const removed=b[b.length-1];fs.push(frame(`Before POP, TOP points to ${removed}.`,{array:b},{highlight:[b.length-1],pointerLabel:'TOP → '+removed}));fs.push(frame(`Remove the element ${removed} from TOP.`,{array:b.slice(0,-1)},{pointerLabel:'REMOVE TOP'}));fs.push(frame(`Move TOP to ${f.length?f[f.length-1]:'empty'}. Resultant stack: [${f.join(', ')}].`,{array:f},{highlight:f.length?[f.length-1]:[],pointerLabel:f.length?'TOP → '+f[f.length-1]:'STACK EMPTY'}));}else if(action.includes('peek')){fs.push(frame(`PEEK reads the current TOP without removing anything.`,{array:f},{highlight:[f.length-1],pointerLabel:'PEEK'}));fs.push(frame(`TOP = ${f[f.length-1]}. The stack remains unchanged: [${f.join(', ')}].`,{array:f},{highlight:[f.length-1],pointerLabel:'TOP → '+f[f.length-1]}));}else{fs.push(frame(`Display reads the stack from BOTTOM to TOP.`,{array:f},{pointerLabel:'DISPLAY'}));f.forEach((v,i)=>fs.push(frame(`Position ${i} contains ${v}${i===f.length-1?' and TOP points here.':'.'}`,{array:f},{highlight:[i],pointerLabel:i===f.length-1?'TOP':'POSITION '+i})));}if(!fs.length)fs.push(frame(d.message,{array:f}));return fs}if(moduleName==='queue'){a.forEach((v,i)=>fs.push(frame(`Queue position ${i} stores ${v}. ${i===0?'FRONT points here.':i===a.length-1?'REAR points here.':''}`,{array:a},{highlight:[i],pointerLabel:i===0?'FRONT':i===a.length-1?'REAR':'QUEUE'})));if(!fs.length)fs.push(frame(d.message,{array:a}));return fs}if(moduleName==='tree'){const n=after.nodes||[];(d.steps||[]).forEach((s,i)=>fs.push(frame(s,{nodes:n},{highlight:[],pointerLabel:`TREE STEP ${i+1}`})));fs.push(frame(d.message,{nodes:n},{highlight:d.highlight||[],pointerLabel:'FINAL TREE'}));return fs}if(moduleName==='graph'){(d.steps||[]).forEach((s,i)=>fs.push(frame(s,{graph:after.graph},{highlight:(d.highlight||[]).slice(0,Math.max(1,i+1)),pointerLabel:`GRAPH STEP ${i+1}`})));return fs}if(moduleName==='hashing'){const b=after.buckets||state.hash;for(let i=0;i<10;i++)fs.push(frame(`Inspect bucket ${i}. ${b[i].length?`It contains ${b[i].join(' → ')}.`:'It is empty.'}`,{buckets:b},{highlight:i,pointerLabel:`BUCKET ${i}`}));return fs}return [frame(d.message,after)]}
function setControlsDisabled(disabled){document.querySelectorAll('#controlsArea button,#controlsArea input').forEach(el=>{el.disabled=disabled});}
