/* ===== DataVerse V5: complete notes + reliable note opening ===== */
const DATAVERSE_NOTES_V5 = {'Class & Object': ('OOP', 'A class is a blueprint and an object is an instance of that class.', ['A class defines data members and member functions.', 'An object is created from a class.', 'Many objects can be created from one class.', 'DataVerse example: ArrayModule is a class and arrayModule is an object.'], 'class Student { public: int age; }; Student s1;'), 'Encapsulation': ('OOP', 'Encapsulation bundles data and methods and controls access to internal data.', ['Private members hide internal state.', 'Public functions provide controlled access.', 'It improves safety and maintainability.', 'DataVerse uses private data with public operations.'], 'private: vector<int> data; public: void display();'), 'Abstraction': ('OOP', 'Abstraction shows what an object can do while hiding implementation details.', ['Users call a simple public operation.', 'Internal steps remain hidden.', 'It reduces unnecessary complexity.', 'insertElement(position,value) hides the shifting logic.'], 'arrayModule.insertElement(2, 50);'), 'Inheritance': ('OOP', 'Inheritance allows a derived class to reuse and extend an existing base class.', ['The base class provides common members.', 'A derived class inherits accessible members.', 'It supports code reuse and hierarchical design.', 'Common types: single, multilevel, multiple, hierarchical and hybrid.'], 'class Animal {}; class Dog : public Animal {};'), 'Polymorphism': ('OOP', 'Polymorphism allows one interface to represent different behaviors.', ['Compile-time polymorphism includes function/operator overloading.', 'Runtime polymorphism commonly uses virtual functions and overriding.', 'It supports flexible and extensible design.', 'The original ArrayModule prototype does not explicitly implement runtime polymorphism.'], 'virtual void show();'), 'Constructor & Destructor': ('OOP', 'A constructor initializes an object; a destructor performs cleanup when an object is destroyed.', ['A constructor has the same name as the class.', 'A constructor has no return type.', 'A destructor uses ~ before the class name.', 'C++ can provide compiler-generated versions when they are not written.'], 'Student() { } ~Student() { }'), 'Composition': ('OOP', 'Composition represents a HAS-A relationship where one class contains another object.', ['The containing class uses another object as a component.', 'It helps build large systems from smaller components.', "DataVerse's ExperimentManager contains an ArrayModule object.", 'This is a direct OOP relationship in the original prototype.'], 'class ExperimentManager { ArrayModule arrayModule; };'), 'Time & Space Complexity': ('DSA', "Complexity describes how an algorithm's time and memory requirements grow with input size.", ['Big-O describes growth rate.', 'O(1) is constant time.', 'O(log n) is logarithmic.', 'O(n) is linear.', 'O(n²) often comes from nested loops.', 'Space complexity measures additional memory.'], 'Linear search: O(n) time, O(1) auxiliary space.'), 'Array': ('DSA', 'An array stores elements in contiguous, index-based positions.', ['Indexing gives direct access.', 'Access by index is typically O(1).', 'Middle insertion/deletion may require shifting.', 'Arrays are useful for fast indexed access.'], 'arr[0], arr[1], arr[2]'), 'Linked List': ('DSA', 'A linked list stores data in nodes connected by links.', ['Each node contains data and a next link.', 'HEAD identifies the first node.', 'The final node points to NULL.', 'Insertion/deletion can be efficient when the correct link is known.'], 'HEAD → [10|NEXT] → [20|NEXT] → [30|NULL]'), 'Stack': ('DSA', 'A stack follows LIFO: Last In, First Out.', ['Push adds at TOP.', 'Pop removes TOP.', 'Peek reads TOP without removing it.', 'Display shows the current stack.', 'A stack can be implemented using an array or linked list.'], 'TOP → 30 → 20 → 10'), 'Queue': ('DSA', 'A queue follows FIFO: First In, First Out.', ['Enqueue adds at REAR.', 'Dequeue removes from FRONT.', 'Front/Peek reads the first element.', 'Queues are useful for scheduling and waiting-line problems.'], 'FRONT → 10 → 20 → 30 ← REAR'), 'Binary Tree / BST': ('DSA', 'A binary tree has at most two children; a BST maintains an ordering rule.', ['A node can have left and right children.', 'In a BST, smaller keys go left and larger keys go right.', 'Inorder traversal of a BST gives sorted order.', 'Common traversals are inorder, preorder and postorder.'], '      50\n     /  \\\n   30    70\n  / \\    / \\\n20  40  60  80'), 'Graph': ('DSA', 'A graph consists of vertices connected by edges.', ['Graphs may be directed or undirected.', 'Edges represent relationships.', 'BFS explores level by level using a queue.', 'DFS explores deeply using recursion or a stack.'], 'A — B — D\n|   |\nC — E'), 'Hashing': ('DSA', 'Hashing maps keys to table positions using a hash function.', ['A hash function maps a key to a bucket/index.', 'A collision happens when keys map to the same bucket.', 'Chaining stores multiple entries in a bucket.', 'A good hash function distributes keys.'], 'index = key % tableSize'), 'Searching': ('DSA', 'Searching finds whether a target exists and where it occurs.', ['Linear search checks elements sequentially.', 'Binary search repeatedly halves a sorted range.', 'Binary search requires sorted data.', 'The DataVerse visualization shows the pointer/range decisions.'], 'Binary search: low → mid → high'), 'Sorting': ('DSA', 'Sorting rearranges elements into an order such as ascending or descending.', ['Bubble sort compares adjacent elements.', 'Selection sort repeatedly selects a minimum/maximum.', 'Insertion sort inserts an item into its correct earlier position.', 'Merge sort divides, sorts and merges subarrays.'], '5, 2, 4, 1 → 1, 2, 4, 5')};

function renderDataVerseNoteV5(name) {
  const n = DATAVERSE_NOTES_V5[name];
  if (!n) return false;
  const selectors = ['#notesContent', '.notes-content', '[data-notes-content]', '#notes-panel-content'];
  let panel = null;
  for (const s of selectors) {
    panel = document.querySelector(s);
    if (panel) break;
  }
  if (!panel) {
    // If the existing notes UI has no content target, create one inside the notes section.
    const host = document.querySelector('#notes, .notes, [data-section="notes"], [data-module="notes"]');
    if (host) {
      panel = document.createElement('div');
      panel.id = 'notesContent';
      panel.className = 'notes-content';
      host.appendChild(panel);
    }
  }
  if (!panel) return false;

  panel.innerHTML = `
    <div class="dv-note-head">
      <span class="dv-note-cat">${n[0]}</span>
      <h2>${name}</h2>
      <p>${n[1]}</p>
    </div>
    <section class="dv-note-section">
      <h3>Key points</h3>
      <ul>${n[2].map(x => `<li>${x}</li>`).join('')}</ul>
    </section>
    <section class="dv-note-section">
      <h3>Example / Revision</h3>
      <pre>${n[3]}</pre>
    </section>
  `;
  panel.setAttribute('aria-live', 'polite');
  return true;
}

window.openDataVerseNote = renderDataVerseNoteV5;

(function setupDataVerseNotesV5() {
  if (window.__dvNotesV5) return;
  window.__dvNotesV5 = true;

  function wire() {
    document.addEventListener('click', function(e) {
      const el = e.target.closest('[data-note]');
      if (!el) return;
      e.preventDefault();
      e.stopPropagation();
      renderDataVerseNoteV5(el.getAttribute('data-note'));
    }, true);

    // Existing cards whose visible label exactly matches a note are automatically wired.
    document.querySelectorAll('button, a, .note-card, .concept-card').forEach(el => {
      const label = (el.textContent || '').replace(/\s+/g, ' ').trim();
      if (DATAVERSE_NOTES_V5[label] && !el.hasAttribute('data-note')) {
        el.setAttribute('data-note', label);
      }
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', wire, {once:true});
  else wire();
})();


/* ===== DataVerse V6: Detailed Notes ===== */
const DATAVERSE_DETAILED_NOTES = {"Class & Object": {"category": "OOP", "title": "Class & Object", "intro": "A class is a blueprint that defines the data and functions an object will have. An object is an instance of a class created from that blueprint.", "bullets": ["A class defines data members and member functions.", "An object is a real instance created from a class.", "Multiple objects can be created from one class.", "In DataVerse, ArrayModule is a class and arrayModule is an object of that class."], "example": "class Student\n{\npublic:\n    int age;\n};\n\nStudent s1;", "visual": "CLASS\n┌────────────────────┐\n│ Student             │\n│ data: age           │\n│ function: display() │\n└──────────┬─────────┘\n           │ creates\n      ┌────┴────┐\n      │ OBJECT  │\n      │ s1      │\n      └─────────┘", "viva": "Class = blueprint; Object = instance of a class."}, "Encapsulation": {"category": "OOP", "title": "Encapsulation", "intro": "Encapsulation is the process of bundling data and the functions that operate on that data into one unit while restricting direct access to internal data.", "bullets": ["Private data cannot be accessed directly from outside the class.", "Public functions provide controlled access to the data.", "It improves data safety and maintainability.", "DataVerse's ArrayModule keeps its vector data private and exposes operations through public functions."], "example": "class ArrayModule\n{\nprivate:\n    vector<int> data;\n\npublic:\n    void display();\n    void insertElement(int position, int value);\n};", "visual": "OUTSIDE USER\n      │\n      ▼\n┌────────────────────────┐\n│      ArrayModule       │\n│                        │\n│  PRIVATE: data         │\n│       ▲                │\n│       │ controlled     │\n│       │ access         │\n│  PUBLIC: display()     │\n│          insert()      │\n└────────────────────────┘", "viva": "Encapsulation = data + methods together with controlled access."}, "Abstraction": {"category": "OOP", "title": "Abstraction", "intro": "Abstraction means exposing the essential operation to the user while hiding the internal implementation details.", "bullets": ["The user sees what an operation does rather than every internal step.", "Implementation details remain inside the class.", "It reduces complexity for the user.", "In DataVerse, insertElement(position, value) hides the shifting implementation."], "example": "arrayModule.insertElement(2, 50);\n\n// User does not need to manually shift every element.", "visual": "USER\n  │\n  │ insertElement(2,50)\n  ▼\n┌─────────────────────┐\n│   PUBLIC INTERFACE  │\n├─────────────────────┤\n│ validation          │\n│ create space        │\n│ shift elements      │\n│ insert value        │\n│ update state        │\n└─────────────────────┘", "viva": "Abstraction = show essential functionality, hide implementation."}, "Inheritance": {"category": "OOP", "title": "Inheritance", "intro": "Inheritance is one of the fundamental concepts of Object-Oriented Programming (OOP) that allows a class to acquire the properties and behaviors of another class. It promotes code reusability by enabling new classes to extend existing classes instead of rewriting code.", "bullets": ["Allows derived classes to reuse members of an existing class.", "Supports code reusability and hierarchical class design.", "The existing class is called the base or parent class.", "The new class is called the derived or child class.", "Common forms are single, multilevel, multiple, hierarchical and hybrid inheritance."], "example": "#include <iostream>\nusing namespace std;\n\nclass Animal\n{\npublic:\n    void sound()\n    {\n        cout << \"Animal makes a sound\" << endl;\n    }\n};\n\nclass Dog : public Animal\n{\npublic:\n    void bark()\n    {\n        cout << \"Dog barks\" << endl;\n    }\n};\n\nint main()\n{\n    Dog d;\n    d.sound();   // inherited\n    d.bark();    // own function\n}", "visual": "                 ┌─────────────────┐\n                 │   ANIMAL CLASS   │\n                 │   Base / Parent  │\n                 └────────┬────────┘\n                          │\n              inherits    │\n          ┌───────────────┼───────────────┐\n          ▼               ▼               ▼\n   ┌────────────┐  ┌────────────┐  ┌────────────┐\n   │ DOG CLASS  │  │ CAT CLASS  │  │ COW CLASS  │\n   │  Derived   │  │  Derived   │  │  Derived   │\n   └────────────┘  └────────────┘  └────────────┘", "viva": "Inheritance = IS-A relationship and code reuse. Example: Dog IS-A Animal."}, "Polymorphism": {"category": "OOP", "title": "Polymorphism", "intro": "Polymorphism means 'many forms'. The same interface or function name can produce different behavior depending on the situation.", "bullets": ["Compile-time polymorphism includes function overloading and operator overloading.", "Runtime polymorphism commonly uses virtual functions and overriding.", "It allows a common interface for different derived-class behaviors.", "The original ArrayModule prototype does not explicitly implement runtime polymorphism."], "example": "class Animal\n{\npublic:\n    virtual void sound() { cout << \"Animal\"; }\n};\n\nclass Dog : public Animal\n{\npublic:\n    void sound() override { cout << \"Dog\"; }\n};", "visual": "             Animal*\n                │\n          calls sound()\n                │\n        ┌───────┴───────┐\n        ▼               ▼\n      Dog             Cat\n    \"Bark\"            \"Meow\"", "viva": "Polymorphism = one interface, many forms/behaviors."}, "Constructor & Destructor": {"category": "OOP", "title": "Constructor & Destructor", "intro": "A constructor is a special member function that runs when an object is created. A destructor runs when the object's lifetime ends and is used for cleanup.", "bullets": ["A constructor has the same name as the class.", "A constructor has no return type.", "A destructor uses ~ followed by the class name.", "Constructors can initialize data members.", "C++ can provide compiler-generated constructors/destructors when they are not explicitly written."], "example": "class Student\n{\npublic:\n    Student() { cout << \"Created\"; }\n    ~Student() { cout << \"Destroyed\"; }\n};", "visual": "object created\n      ↓\n CONSTRUCTOR\n      ↓\n object initialized\n      ↓\n object used\n      ↓\n object lifetime ends\n      ↓\n  DESTRUCTOR", "viva": "Constructor initializes; destructor cleans up."}, "Composition": {"category": "OOP", "title": "Composition", "intro": "Composition represents a HAS-A relationship in which one class contains an object of another class as a component.", "bullets": ["The containing class is built from other objects.", "It supports modular system design.", "DataVerse's ExperimentManager contains an ArrayModule object.", "Composition is different from inheritance: HAS-A versus IS-A."], "example": "class ExperimentManager\n{\nprivate:\n    ArrayModule arrayModule;\n};", "visual": "┌─────────────────────────────┐\n│     ExperimentManager       │\n│                             │\n│   HAS-A                     │\n│   ┌─────────────────────┐   │\n│   │     ArrayModule     │   │\n│   └─────────────────────┘   │\n└─────────────────────────────┘", "viva": "Composition = HAS-A relationship. Inheritance = IS-A relationship."}, "Time & Space Complexity": {"category": "DSA", "title": "Time & Space Complexity", "intro": "Complexity measures how the running time and memory requirements of an algorithm grow as the input size increases.", "bullets": ["Time complexity describes growth in execution steps.", "Space complexity describes additional memory used.", "Big-O expresses the growth rate for algorithm analysis.", "Common classes include O(1), O(log n), O(n), O(n log n), and O(n²)."], "example": "for (int i = 0; i < n; i++)\n{\n    cout << i;\n}\n\nTime: O(n)\nAuxiliary space: O(1)", "visual": "Input n grows → work grows\n\nO(1)       ─────\nO(log n)   ─────╱\nO(n)       ────╱\nO(n²)      ───╱╱", "viva": "Big-O focuses on growth rate rather than exact machine time."}, "Array": {"category": "DSA", "title": "Array", "intro": "An array stores elements in contiguous memory locations and provides index-based access.", "bullets": ["Elements are accessed using indexes.", "Access by index is typically O(1).", "Insertion/deletion in the middle may require shifting.", "Arrays are useful when fast indexed access is important."], "example": "int arr[4] = {10, 20, 30, 40};\n\nIndex:  0   1   2   3\nValue: 10  20  30  40", "visual": "index   0     1     2     3\n       ┌────┬────┬────┬────┐\n       │ 10 │ 20 │ 30 │ 40 │\n       └────┴────┴────┴────┘", "viva": "Array access O(1); middle insertion/deletion generally O(n)."}, "Linked List": {"category": "DSA", "title": "Linked List", "intro": "A linked list stores elements in nodes. Each node contains data and a link/reference to the next node.", "bullets": ["HEAD points to the first node.", "Each node stores DATA and NEXT.", "The last node points to NULL.", "Nodes do not need to be contiguous in memory.", "Insertion/deletion can be efficient when the required node/reference is known."], "example": "HEAD → [10 | NEXT] → [20 | NEXT] → [30 | NULL]", "visual": "HEAD\n ↓\n┌───────┐    ┌───────┐    ┌───────┐\n│10 | •─┼───►│20 | •─┼───►│30 |NULL│\n└───────┘    └───────┘    └───────┘", "viva": "Linked list = nodes connected by links; traversal/search O(n)."}, "Stack": {"category": "DSA", "title": "Stack", "intro": "A stack is a linear data structure that follows LIFO: Last In, First Out.", "bullets": ["Push inserts an element at TOP.", "Pop removes the element at TOP.", "Peek reads TOP without removing it.", "Display shows the current stack.", "Stack can be implemented using an array or linked list."], "example": "Push 10 → Push 20 → Push 30\n\nTOP → 30 → 20 → 10", "visual": "       TOP\n        ↓\n     ┌─────┐\n     │ 30  │ ← push/pop here\n     ├─────┤\n     │ 20  │\n     ├─────┤\n     │ 10  │\n     └─────┘", "viva": "Stack = LIFO. Push, Pop and Peek are typically O(1)."}, "Queue": {"category": "DSA", "title": "Queue", "intro": "A queue is a linear data structure that follows FIFO: First In, First Out.", "bullets": ["Enqueue inserts at REAR.", "Dequeue removes from FRONT.", "Front/Peek reads the first element.", "Queues model waiting lines and scheduling systems.", "A queue can be implemented using arrays or linked lists."], "example": "ENQUEUE 10, 20, 30\n\nFRONT → 10 → 20 → 30 ← REAR", "visual": "FRONT                          REAR\n  ↓                               ↓\n┌─────┬─────┬─────┐\n│ 10  │ 20  │ 30  │\n└─────┴─────┴─────┘\n  ↑ removed                 ↑ inserted", "viva": "Queue = FIFO. With a suitable implementation enqueue/dequeue can be O(1)."}, "Binary Tree / BST": {"category": "DSA", "title": "Binary Tree / Binary Search Tree", "intro": "A binary tree is a tree in which each node has at most two children. A Binary Search Tree (BST) maintains an ordering rule.", "bullets": ["Each node can have a left and right child.", "In a BST, smaller values go left and larger values go right.", "Inorder traversal of a BST produces sorted order.", "Common traversals are inorder, preorder and postorder."], "example": "        50\n       /  \\\n     30    70\n    /  \\  /  \\\n   20 40 60 80", "visual": "              50\n            /    \\\n          30      70\n         /  \\    /  \\\n       20   40  60   80", "viva": "Balanced BST search/insert/delete is O(log n) average; worst case O(n)."}, "Graph": {"category": "DSA", "title": "Graph", "intro": "A graph is a non-linear data structure made of vertices (nodes) and edges (connections).", "bullets": ["Vertices represent entities or points.", "Edges represent relationships/connections.", "Graphs can be directed or undirected.", "BFS explores level by level using a queue.", "DFS explores deeply using recursion or a stack."], "example": "A — B — D\n|   |\nC — E", "visual": "      A ───── B ───── D\n      │       │\n      │       │\n      C ───── E", "viva": "BFS/DFS are O(V + E) with an adjacency-list representation."}, "Hashing": {"category": "DSA", "title": "Hashing", "intro": "Hashing maps a key to a location in a hash table using a hash function.", "bullets": ["The hash function converts a key into an index/bucket.", "A collision occurs when multiple keys map to the same bucket.", "Chaining stores multiple entries in a bucket.", "A good hash function distributes keys across the table."], "example": "tableSize = 10\nindex = key % tableSize\n\n27 % 10 = 7", "visual": "KEY 27\n  │\n  ▼\nhash: key % 10\n  │\n  ▼\nBUCKET 7 → [27]", "viva": "Hashing average search/insert/delete O(1); worst case can be O(n)."}, "Searching": {"category": "DSA", "title": "Searching", "intro": "Searching is the process of finding whether a target value exists in a data structure and locating its position.", "bullets": ["Linear search checks elements one by one.", "Binary search repeatedly divides a sorted range.", "Binary search requires sorted data.", "The DataVerse visualizer shows pointer/range decisions."], "example": "Sorted: 10 20 30 40 50\nTarget: 40\n\nlow=0, high=4, mid=2 → 30\nTarget is larger → move low", "visual": "LOW       MID        HIGH\n ↓          ↓           ↓\n10  20  30  40  50\n           │\n        compare", "viva": "Linear search O(n); binary search O(log n) on sorted data."}, "Sorting": {"category": "DSA", "title": "Sorting", "intro": "Sorting rearranges elements into a chosen order, such as ascending or descending order.", "bullets": ["Bubble sort compares adjacent elements and swaps them when needed.", "Selection sort repeatedly selects the minimum/maximum.", "Insertion sort inserts each element into its correct earlier position.", "Merge sort divides the data, sorts subarrays and merges them."], "example": "Before: 5 2 4 1\nAfter:  1 2 4 5", "visual": "5  2  4  1\n↓  compare / swap / shift\n1  2  4  5", "viva": "Bubble/Selection/Insertion are typically O(n²); Merge sort O(n log n)."}};

function openDetailedDataVerseNote(name) {
  const n = DATAVERSE_DETAILED_NOTES[name];
  if (!n) return false;

  let panel = document.querySelector('#notesContent, .notes-content, [data-notes-content], #notes-panel-content');
  if (!panel) {
    const host = document.querySelector('#notes, .notes, [data-section="notes"], [data-module="notes"]');
    if (host) {
      panel = document.createElement('div');
      panel.id = 'notesContent';
      panel.className = 'notes-content';
      host.appendChild(panel);
    }
  }
  if (!panel) return false;

  const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  panel.innerHTML = `
    <article class="dv-detailed-note">
      <div class="dv-detailed-note-head">
        <span class="dv-note-cat">${esc(n.category)}</span>
        <h2>${esc(n.title)}</h2>
        <p>${esc(n.intro)}</p>
      </div>
      <div class="dv-detailed-section">
        <h3>Key Points</h3>
        <ul>${n.bullets.map(x => `<li>${esc(x)}</li>`).join('')}</ul>
      </div>
      <div class="dv-detailed-section">
        <h3>Visual Explanation</h3>
        <pre class="dv-note-diagram">${esc(n.visual)}</pre>
      </div>
      <div class="dv-detailed-section">
        <h3>Example</h3>
        <pre class="dv-note-code">${esc(n.example)}</pre>
      </div>
      <div class="dv-viva-box">
        <strong>Quick Viva Point</strong>
        <p>${esc(n.viva)}</p>
      </div>
    </article>`;
  panel.setAttribute('aria-live','polite');
  return true;
}

window.openDataVerseNote = openDetailedDataVerseNote;
window.DATAVERSE_NOTES_V5 = DATAVERSE_DETAILED_NOTES;

(function setupDetailedNotes() {
  if (window.__dvDetailedNotes) return;
  window.__dvDetailedNotes = true;

  function wireNoteCards() {
    document.querySelectorAll('[data-note]').forEach(el => {
      const name = el.getAttribute('data-note');
      if (DATAVERSE_DETAILED_NOTES[name]) {
        el.title = 'Open detailed notes: ' + name;
      }
    });

    document.addEventListener('click', function(e) {
      const card = e.target.closest('[data-note]');
      if (!card) return;
      const name = card.getAttribute('data-note');
      if (DATAVERSE_DETAILED_NOTES[name]) {
        e.preventDefault();
        e.stopPropagation();
        openDetailedDataVerseNote(name);
      }
    }, true);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', wireNoteCards, {once:true});
  } else {
    wireNoteCards();
  }
})();
